artifacts.solve_py:
#!/usr/bin/env python3
import os, csv, sys, math
from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions/solution.csv"

def read_csv(name):
    with open(os.path.join(DATA, name), newline='') as f:
        return list(csv.DictReader(f))

months = read_csv("months.csv")
M = [r["month"] for r in months]
Midx = {r["month"]: int(r["period_index"]) for r in months}
Mset = set(M)

products = read_csv("products.csv")
P = [r["product_id"] for r in products]
hold_mult = {r["product_id"]: float(r["inventory_holding_multiplier"]) for r in products}
short_mult = {r["product_id"]: float(r["shortage_penalty_multiplier"]) for r in products}

materials = read_csv("materials.csv")
MAT = [r["material_id"] for r in materials]

bom = {}
for r in read_csv("material_bom.csv"):
    bom[(r["product_id"], r["material_id"])] = float(r["tons_material_per_ton_product"])

plants = read_csv("plants.csv")
PL = [r["plant_id"] for r in plants]
reg_cap = {r["plant_id"]: float(r["regular_capacity_tons"]) for r in plants}
ot_cap = {r["plant_id"]: float(r["overtime_capacity_tons"]) for r in plants}
min_run = {r["plant_id"]: float(r["min_run_tons"]) for r in plants}
fixed_op = {r["plant_id"]: float(r["fixed_operating_cost"]) for r in plants}
startup_cost = {r["plant_id"]: float(r["startup_cost"]) for r in plants}
initial_open = {r["plant_id"]: int(r["initial_open"]) for r in plants}
min_uptime = {r["plant_id"]: int(r["min_uptime_months"]) for r in plants}

ppc = {}
for r in read_csv("plant_product_costs.csv"):
    ppc[(r["plant_id"], r["product_id"])] = {
        "reg": float(r["regular_conversion_cost_per_ton"]),
        "ot": float(r["overtime_premium_cost_per_ton"]),
        "regc": float(r["regular_capacity_consumption_per_ton"]),
        "otc": float(r["overtime_capacity_consumption_per_ton"]),
        "co2": float(r["process_co2_kg_per_ton"]),
    }

ppr = {}
for r in read_csv("plant_product_rules.csv"):
    ppr[(r["plant_id"], r["product_id"])] = {
        "qual": r["qualified_from_month"],
        "minb": float(r["min_batch_tons_if_produced"]),
        "maxo": float(r["max_monthly_output_tons"]),
        "setup": float(r["setup_cost_per_month"]),
    }

matsup = {}
for r in read_csv("material_supply.csv"):
    matsup[(r["month"], r["plant_id"], r["material_id"])] = {
        "max": float(r["max_purchase_tons"]),
        "cost": float(r["purchase_cost_per_ton"]),
        "co2": float(r["material_co2_kg_per_ton"]),
    }

matcon = {}
for r in read_csv("material_contracts.csv"):
    matcon[(r["month"], r["plant_id"], r["material_id"])] = float(r["min_purchase_tons_if_open"])

dcs = read_csv("distribution_centers.csv")
DC = [r["dc_id"] for r in dcs]
dc_store = {r["dc_id"]: float(r["storage_capacity_tons"]) for r in dcs}
dc_hold = {r["dc_id"]: float(r["holding_cost_per_ton_month"]) for r in dcs}
dc_in = {r["dc_id"]: float(r["inbound_throughput_tons"]) for r in dcs}
dc_out = {r["dc_id"]: float(r["outbound_throughput_tons"]) for r in dcs}

custs = read_csv("customers.csv")
C = [r["customer_id"] for r in custs]
short_pen = {r["customer_id"]: float(r["shortage_penalty_per_ton"]) for r in custs}

demand = {}
for r in read_csv("demand.csv"):
    demand[(r["month"], r["customer_id"], r["product_id"])] = float(r["demand_tons"])

avail = {}
for r in read_csv("plant_month_availability.csv"):
    avail[(r["month"], r["plant_id"])] = (float(r["regular_capacity_factor"]), float(r["overtime_capacity_factor"]))

pdc_routes = {}
for r in read_csv("plant_to_dc_routes.csv"):
    pdc_routes[(r["plant_id"], r["dc_id"])] = {
        "cost": float(r["transport_cost_per_ton"]),
        "cap": float(r["monthly_capacity_tons"]),
        "co2": float(r["transport_co2_kg_per_ton"]),
        "fixed": float(r["fixed_cost_per_month"]),
        "minsh": float(r["min_shipment_tons_if_used"]),
    }

dcr_routes = {}
for r in read_csv("dc_to_customer_routes.csv"):
    dcr_routes[(r["dc_id"], r["customer_id"])] = {
        "cost": float(r["transport_cost_per_ton"]),
        "cap": float(r["monthly_capacity_tons"]),
        "co2": float(r["transport_co2_kg_per_ton"]),
        "fixed": float(r["fixed_cost_per_month"]),
        "minsh": float(r["min_shipment_tons_if_used"]),
    }

safety = {}
for r in read_csv("safety_stock.csv"):
    safety[(r["month"], r["dc_id"], r["product_id"])] = float(r["min_inventory_tons"])

inv_cap = {}
for r in read_csv("inventory_caps.csv"):
    inv_cap[(r["month"], r["dc_id"], r["product_id"])] = float(r["max_inventory_tons"])

svc = {}
for r in read_csv("customer_service_requirements.csv"):
    svc[(r["customer_id"], r["product_id"])] = {
        "fill": float(r["min_horizon_fill_rate"]),
        "maxshort": float(r["max_monthly_shortage_fraction"]),
    }

co2bud = {r["month"]: float(r["co2_budget_kg"]) for r in read_csv("monthly_co2_budget.csv")}

excl = set()
for r in read_csv("route_product_exceptions.csv"):
    if r["allowed"] == "0":
        if r["route_type"] == "plant_dc":
            excl.add(("pdc", r["from_id"], r["to_id"], r["product_id"]))
        else:
            excl.add(("dcr", r["from_id"], r["to_id"], r["product_id"]))

share_rules = []
for r in read_csv("customer_product_share_rules.csv"):
    dclist = [d for d in r["dc_ids"].split(";") if d]
    share_rules.append((r["customer_id"], r["product_id"], dclist, float(r["min_horizon_share"])))

split_rules = []
for r in read_csv("split_delivery_rules.csv"):
    split_rules.append((r["month"], r["customer_id"], r["product_id"], r["dc_id"], float(r["min_fraction_of_demand"])))

# transport modes
mode_cost_mult = {}
mode_co2_mult = {}
mode_cap = {}
mode_min = {}
lane_modes = {}  # (route_type, from, to) -> list of modes
for r in read_csv("transport_modes.csv"):
    key = (r["route_type"], r["from_id"], r["to_id"])
    mode_cost_mult[(key, r["mode_id"])] = float(r["cost_multiplier"])
    mode_co2_mult[(key, r["mode_id"])] = float(r["co2_multiplier"])
    mode_cap[(key, r["mode_id"])] = float(r["monthly_capacity_tons"])
    mode_min[(key, r["mode_id"])] = float(r["min_mode_tons_if_used"])
    lane_modes.setdefault(key, []).append(r["mode_id"])

monthly_mode_cap = {}
monthly_mode_min = {}
for r in read_csv("monthly_mode_capacity.csv"):
    monthly_mode_cap[(r["month"], r["mode_id"])] = float(r["max_tons"])
    monthly_mode_min[(r["month"], r["mode_id"])] = float(r["min_tons_if_used"])

# Build model
model = Model("industrial_supply_planning")
model.setParam("gaprel", 0.0005)
time_limit = 300.0
env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env_limit is not None:
    try:
        time_limit = min(time_limit, float(env_limit))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

# Variables
open_ = {}   # plant open
start_ = {}  # plant startup
setup = {}   # plant-product campaign setup
prod_reg = {}
prod_ot = {}
mat_buy = {}
ship_pdc = {}  # (m, p, dc, prod)
ship_dcr = {}  # (m, dc, c, prod)
inv = {}       # (m, dc, prod)
short = {}     # (m, c, prod)

# Lane activation binaries
act_pdc = {}  # (m, p, dc)
act_dcr = {}  # (m, dc, c)

# Mode usage binaries (per lane-mode-month)
use_mode_pdc = {}  # (m, p, dc, mode)
use_mode_dcr = {}  # (m, dc, c, mode)

# Objective coefficients (tracked in dicts)
obj_terms = []

# Production variables
for m in M:
    for p in PL:
        open_[(m, p)] = model.addVar(name=f"open_{m}_{p}", vtype="B", lb=0, ub=1, obj=0.0)
        start_[(m, p)] = model.addVar(name=f"start_{m}_{p}", vtype="B", lb=0, ub=1, obj=0.0)
        for prod in P:
            if (p, prod) in ppr:
                rule = ppr[(p, prod)]
                if Midx[m] >= Midx[rule["qual"]]:
                    setup[(m, p, prod)] = model.addVar(name=f"setup_{m}_{p}_{prod}", vtype="B", lb=0, ub=1, obj=0.0)
                    prod_reg[(m, p, prod)] = model.addVar(name=f"prod_reg_{m}_{p}_{prod}", vtype="C", lb=0, ub=rule["maxo"], obj=0.0)
                    prod_ot[(m, p, prod)] = model.addVar(name=f"prod_ot_{m}_{p}_{prod}", vtype="C", lb=0, ub=rule["maxo"], obj=0.0)

# Material purchase variables
for m in M:
    for p in PL:
        for mat in MAT:
            if (m, p, mat) in matsup:
                mat_buy[(m, p, mat)] = model.addVar(name=f"mat_{m}_{p}_{mat}", vtype="C", lb=0, ub=matsup[(m, p, mat)]["max"], obj=0.0)

# Shipment variables
for m in M:
    for (p, dc), info in pdc_routes.items():
        for prod in P:
            if ("pdc", p, dc, prod) in excl:
                continue
            ship_pdc[(m, p, dc, prod)] = model.addVar(name=f"ship_pdc_{m}_{p}_{dc}_{prod}", vtype="C", lb=0, ub=info["cap"], obj=0.0)
    for (p, dc) in pdc_routes:
        act_pdc[(m, p, dc)] = model.addVar(name=f"act_pdc_{m}_{p}_{dc}", vtype="B", lb=0, ub=1, obj=0.0)
        for mode in lane_modes.get(("plant_dc", p, dc), []):
            use_mode_pdc[(m, p, dc, mode)] = model.addVar(name=f"use_pdc_{m}_{p}_{dc}_{mode}", vtype="B", lb=0, ub=1, obj=0.0)

    for (dc, c), info in dcr_routes.items():
        for prod in P:
            if ("dcr", dc, c, prod) in excl:
                continue
            ship_dcr[(m, dc, c, prod)] = model.addVar(name=f"ship_dcr_{m}_{dc}_{c}_{prod}", vtype="C", lb=0, ub=info["cap"], obj=0.0)
    for (dc, c) in dcr_routes:
        act_dcr[(m, dc, c)] = model.addVar(name=f"act_dcr_{m}_{dc}_{c}", vtype="B", lb=0, ub=1, obj=0.0)
        for mode in lane_modes.get(("dc_customer", dc, c), []):
            use_mode_dcr[(m, dc, c, mode)] = model.addVar(name=f"use_dcr_{m}_{dc}_{c}_{mode}", vtype="B", lb=0, ub=1, obj=0.0)

    for dc in DC:
        for prod in P:
            inv[(m, dc, prod)] = model.addVar(name=f"inv_{m}_{dc}_{prod}", vtype="C", lb=0, ub=dc_store[dc], obj=0.0)
    for c in C:
        for prod in P:
            short[(m, c, prod)] = model.addVar(name=f"short_{m}_{c}_{prod}", vtype="C", lb=0, ub=demand.get((m, c, prod), 0.0), obj=0.0)

# Objective
obj_expr = 0.0
for m in M:
    for p in PL:
        obj_expr += fixed_op[p] * open_[(m, p)]
        obj_expr += startup_cost[p] * start_[(m, p)]
        for prod in P:
            if (m, p, prod) in prod_reg:
                c = ppc[(p, prod)]
                obj_expr += c["reg"] * prod_reg[(m, p, prod)]
                obj_expr += c["ot"] * prod_ot[(m, p, prod)]
                obj_expr += ppr[(p, prod)]["setup"] * setup[(m, p, prod)]
    for p in PL:
        for mat in MAT:
            if (m, p, mat) in mat_buy:
                obj_expr += matsup[(m, p, mat)]["cost"] * mat_buy[(m, p, mat)]
    for (p, dc), info in pdc_routes.items():
        obj_expr += info["fixed"] * act_pdc[(m, p, dc)]
        for prod in P:
            if (m, p, dc, prod) in ship_pdc:
                for mode in lane_modes.get(("plant_dc", p, dc), []):
                    cm = mode_cost_mult.get(("plant_dc", p, dc, mode), 1.0)
                    obj_expr += info["cost"] * cm * ship_pdc[(m, p, dc, prod)] / max(len(lane_modes.get(("plant_dc", p, dc), [])), 1)
    for (dc, c), info in dcr_routes.items():
        obj_expr += info["fixed"] * act_dcr[(m, dc, c)]
        for prod in P:
            if (m, dc, c, prod) in ship_dcr:
                for mode in lane_modes.get(("dc_customer", dc, c), []):
                    cm = mode_cost_mult.get(("dc_customer", dc, c, mode), 1.0)
                    obj_expr += info["cost"] * cm * ship_dcr[(m, dc, c, prod)] / max(len(lane_modes.get(("dc_customer", dc, c), [])), 1)
    for dc in DC:
        for prod in P:
            obj_expr += dc_hold[dc] * hold_mult[prod] * inv[(m, dc, prod)]
    for c in C:
        for prod in P:
            obj_expr += short_pen[c] * short_mult[prod] * short[(m, c, prod)]

model.setObjective(obj_expr, sense="minimize")

# Constraints
# Plant open/startup logic
for m in M:
    for p in PL:
        if Midx[m] == 1:
            model.addCons(open_[(m, p)] - start_[(m, p)] >= initial_open[p], name=f"open_start_1_{p}")
        else:
            pm = [mm for mm in M if Midx[mm] == Midx[m] - 1][0]
            model.addCons(open_[(m, p)] - open_[(pm, p)] >= start_[(m, p)], name=f"open_start_{m}_{p}")
            model.addCons(start_[(m, p)] >= open_[(m, p)] - open_[(pm, p)], name=f"start_ge_{m}_{p}")
            model.addCons(start_[(m, p)] <= open_[(m, p)], name=f"start_le_{m}_{p}")

# Min uptime
for p in PL:
    mu = min_uptime[p]
    for m in M:
        if Midx[m] == 1:
            continue
        # if started at m, must stay open for mu months
        idx = Midx[m]
        for k in range(mu):
            if idx + k <= 6:
                mk = [mm for mm in M if Midx[mm] == idx + k][0]
                model.addCons(open_[(mk, p)] >= start_[(m, p)], name=f"uptime_{p}_{m}_{k}")

# Campaign setup linking
for m in M:
    for p in PL:
        for prod in P:
            if (m, p, prod) not in setup:
                continue
            rule = ppr[(p, prod)]
            total = prod_reg[(m, p, prod)] + prod_ot[(m, p, prod)]
            model.addCons(total <= rule["maxo"] * setup[(m, p, prod)], name=f"setup_cap_{m}_{p}_{prod}")
            if rule["minb"] > 0:
                model.addCons(total >= rule["minb"] * setup[(m, p, prod)], name=f"setup_min_{m}_{p}_{prod}")
            # setup only if plant open
            model.addCons(setup[(m, p, prod)] <= open_[(m, p)], name=f"setup_open_{m}_{p}_{prod}")

# Plant capacity
for m in M:
    for p in PL:
        rf, of = avail[(m, p)]
        reg_terms = []
        ot_terms = []
        for prod in P:
            if (m, p, prod) in prod_reg:
                c = ppc[(p, prod)]
                reg_terms.append(c["regc"] * prod_reg[(m, p, prod)])
                ot_terms.append(c["otc"] * prod_ot[(m, p, prod)])
        model.addCons(quicksum(reg_terms) <= reg_cap[p] * rf * open_[(m, p)], name=f"regcap_{m}_{p}")
        model.addCons(quicksum(ot_terms) <= ot_cap[p] * of * open_[(m, p)], name=f"otcap_{m}_{p}")

# Min run
for m in M:
    for p in PL:
        total_prod = []
        for prod in P:
            if (m, p, prod) in prod_reg:
                total_prod.append(prod_reg[(m, p, prod)])
                total_prod.append(prod_ot[(m, p, prod)])
        if total_prod:
            model.addCons(quicksum(total_prod) >= min_run[p] * open_[(m, p)], name=f"minrun_{m}_{p}")

# BOM balance
for m in M:
    for p in PL:
        for mat in MAT:
            if (m, p, mat) not in mat_buy:
                continue
            prod_terms = []
            for prod in P:
                if (m, p, prod) in prod_reg and (prod, mat) in bom:
                    prod_terms.append(bom[(prod, mat)] * (prod_reg[(m, p, prod)] + prod_ot[(m, p, prod)]))
            if prod_terms:
                model.addCons(mat_buy[(m, p, mat)] >= quicksum(prod_terms), name=f"bom_{m}_{p}_{mat}")
            else:
                model.addCons(mat_buy[(m, p, mat)] == 0, name=f"bom_zero_{m}_{p}_{mat}")

# Take-or-pay
for (m, p, mat), mn in matcon.items():
    if (m, p, mat) in mat_buy:
        model.addCons(mat_buy[(m, p, mat)] >= mn * open_[(m, p)], name=f"takeorpay_{m}_{p}_{mat}")

# Lane activation and mode constraints
for m in M:
    for (p, dc), info in pdc_routes.items():
        total_lane = []
        for prod in P:
            if (m, p, dc, prod) in ship_pdc:
                total_lane.append(ship_pdc[(m, p, dc, prod)])
        if total_lane:
            model.addCons(quicksum(total_lane) <= info["cap"] * act_pdc[(m, p, dc)], name=f"pdc_cap_{m}_{p}_{dc}")
            if info["minsh"] > 0:
                model.addCons(quicksum(total_lane) >= info["minsh"] * act_pdc[(m, p, dc)], name=f"pdc_min_{m}_{p}_{dc}")
        # mode constraints
        for mode in lane_modes.get(("plant_dc", p, dc), []):
            mv = use_mode_pdc[(m, p, dc, mode)]
            model.addCons(quicksum(total_lane) <= mode_cap[("plant_dc", p, dc, mode)] * mv if total_lane else 0, name=f"pdc_mode_cap_{m}_{p}_{dc}_{mode}")
            if mode_min[("plant_dc", p, dc, mode")] > 0:
                model.addCons(quicksum(total_lane) >= mode_min[("plant_dc", p, dc, mode)] * mv, name=f"pdc_mode_min_{m}_{p}_{dc}_{mode}")
            model.addCons(mv <= act_pdc[(m, p, dc)], name=f"pdc_mode_act_{m}_{p}_{dc}_{mode}")

    for (dc, c), info in dcr_routes.items():
        total_lane = []
        for prod in P:
            if (m, dc, c, prod) in ship_dcr:
                total_lane.append(ship_dcr[(m, dc, c, prod)])
        if total_lane:
            model.addCons(quicksum(total_lane) <= info["cap"] * act_dcr[(m, dc, c)], name=f"dcr_cap_{m}_{dc}_{c}")
            if info["minsh"] > 0:
                model.addCons(quicksum(total_lane) >= info["minsh"] * act_dcr[(m, dc, c)], name=f"dcr_min_{m}_{dc}_{c}")
        for mode in lane_modes.get(("dc_customer", dc, c), []):
            mv = use_mode_dcr[(m, dc, c, mode)]
            model.addCons(quicksum(total_lane) <= mode_cap[("dc_customer", dc, c, mode)] * mv if total_lane else 0, name=f"dcr_mode_cap_{m}_{dc}_{c}_{mode}")
            if mode_min[("dc_customer", dc, c, mode)] > 0:
                model.addCons(quicksum(total_lane) >= mode_min[("dc_customer", dc, c, mode)] * mv, name=f"dcr_mode_min_{m}_{dc}_{c}_{mode}")
            model.addCons(mv <= act_dcr[(m, dc, c)], name=f"dcr_mode_act_{m}_{dc}_{c}_{mode}")

# Monthly mode capacity (aggregate)
for m in M:
    for mode in ["RAIL", "TRUCK"]:
        rail_terms = []
        for (p, dc) in pdc_routes:
            for prod in P:
                if (m, p, dc, prod) in ship_pdc:
                    rail_terms.append(ship_pdc[(m, p, dc, prod)])
        for (dc, c) in dcr_routes:
            for prod in P:
                if (m, dc, c, prod) in ship_dcr:
                    if mode == "TRUCK":
                        rail_terms.append(ship_dcr[(m, dc, c, prod)])
        if rail_terms:
            model.addCons(quicksum(rail_terms) <= monthly_mode_cap[(m, mode)], name=f"mode_cap_{m}_{mode}")

# DC inventory balance
for m in M:
    for dc in DC:
        for prod in P:
            inbound = []
            for p in PL:
                if (m, p, dc, prod) in ship_pdc:
                    inbound.append(ship_pdc[(m, p, dc, prod)])
            outbound = []
            for c in C:
                if (m, dc, c, prod) in ship_dcr:
                    outbound.append(ship_dcr[(m, dc, c, prod)])
            if Midx[m] == 1:
                lhs = quicksum(inbound) - quicksum(outbound)
            else:
                pm = [mm for mm in M if Midx[mm] == Midx[m] - 1][0]
                lhs = inv[(pm, dc, prod)] + quicksum(inbound) - quicksum(outbound)
            model.addCons(lhs == inv[(m, dc, prod)], name=f"invbal_{m}_{dc}_{prod}")

# Safety stock
for (m, dc, prod), mn in safety.items():
    if (m, dc, prod) in inv:
        model.addCons(inv[(m, dc, prod)] >= mn, name=f"safety_{m}_{dc}_{prod}")

# Product inventory caps
for (m, dc, prod), mx in inv_cap.items():
    if (m, dc, prod) in inv:
        model.addCons(inv[(m, dc, prod)] <= mx, name=f"invcap_{m}_{dc}_{prod}")

# DC storage capacity
for m in M:
    for dc in DC:
        terms = [inv[(m, dc, prod)] for prod in P if (m, dc, prod) in inv]
        model.addCons(quicksum(terms) <= dc_store[dc], name=f"storage_{m}_{dc}")

# DC throughput
for m in M:
    for dc in DC:
        in_terms = []
        for p in PL:
            for prod in P:
                if (m, p, dc, prod) in ship_pdc:
                    in_terms.append(ship_pdc[(m, p, dc, prod)])
        model.addCons(quicksum(in_terms) <= dc_in[dc], name=f"inbound_tp_{m}_{dc}")
        out_terms = []
        for c in C:
            for prod in P:
                if (m, dc, c, prod) in ship_dcr:
                    out_terms.append(ship_dcr[(m, dc, c, prod)])
        model.addCons(quicksum(out_terms) <= dc_out[dc], name=f"outbound_tp_{m}_{dc}")

# Demand balance
for m in M:
    for c in C:
        for prod in P:
            d = demand.get((m, c, prod), 0.0)
            recv = []
            for dc in DC:
                if (m, dc, c, prod) in ship_dcr:
                    recv.append(ship_dcr[(m, dc, c, prod)])
            model.addCons(quicksum(recv) + short[(m, c, prod)] == d, name=f"demand_{m}_{c}_{prod}")

# Service level: monthly shortage fraction
for (c, prod), s in svc.items():
    for m in M:
        d = demand.get((m, c, prod), 0.0)
        if d > 0:
            model.addCons(short[(m, c, prod)] <= s["maxshort"] * d, name=f"maxshort_{m}_{c}_{prod}")

# Horizon fill rate
for (c, prod), s in svc.items():
    total_d = sum(demand.get((m, c, prod), 0.0) for m in M)
    if total_d > 0:
        total_short = quicksum(short[(m, c, prod)] for m in M)
        model.addCons(total_short <= (1 - s["fill"]) * total_d, name=f"fillrate_{c}_{prod}")

# Sourcing share rules
for (c, prod, dclist, share) in share_rules:
    total_delivered = []
    approved = []
    for m in M:
        for dc in DC:
            if (m, dc, c, prod) in ship_dcr:
                total_delivered.append(ship_dcr[(m, dc, c, prod)])
                if dc in dclist:
                    approved.append(ship_dcr[(m, dc, c, prod)])
    if total_delivered:
        model.addCons(quicksum(approved) >= share * quicksum(total_delivered), name=f"share_{c}_{prod}")

# Split delivery rules
for (m, c, prod, dc, frac) in split_rules:
    d = demand.get((m, c, prod), 0.0)
    if (m, dc, c, prod) in ship_dcr:
        model.addCons(ship_dcr[(m, dc, c, prod)] >= frac * d, name=f"split_{m}_{c}_{prod}_{dc}")

# CO2 budget
for m in M:
    co2_terms = []
    # material
    for p in PL:
        for mat in MAT:
            if (m, p, mat) in mat_buy:
                co2_terms.append(matsup[(m, p, mat)]["co2"] * mat_buy[(m, p, mat)])
    # process
    for p in PL:
        for prod in P:
            if (m, p, prod) in prod_reg:
                co2_terms.append(ppc[(p, prod)]["co2"] * (prod_reg[(m, p, prod)] + prod_ot[(m, p, prod)]))
    # transport plant-dc
    for (p, dc), info in pdc_routes.items():
        for prod in P:
            if (m, p, dc, prod) in ship_pdc:
                for mode in lane_modes.get(("plant_dc", p, dc), []):
                    co2m = mode_co2_mult.get(("plant_dc", p, dc, mode), 1.0)
                    co2_terms.append(info["co2"] * co2m * ship_pdc[(m, p, dc, prod)] / max(len(lane_modes.get(("plant_dc", p, dc), [])), 1))
    # transport dc-customer
    for (dc, c), info in dcr_routes.items():
        for prod in P:
            if (m, dc, c, prod) in ship_dcr:
                for mode in lane_modes.get(("dc_customer", dc, c), []):
                    co2m = mode_co2_mult.get(("dc_customer", dc, c, mode), 1.0)
                    co2_terms.append(info["co2"] * co2m * ship_dcr[(m, dc, c, prod)] / max(len(lane_modes.get(("dc_customer", dc, c), [])), 1))
    model.addCons(quicksum(co2_terms) <= co2bud[m], name=f"co2_{m}")

# Solve
try:
    model.optimize()
    status = model.getStatus()
    print(f"Status: {status}")
    if model.getNSols() > 0:
        objval = model.getObjVal()
        print(f"Objective: {objval:.2f}")
    else:
        print("No solution found.")
except Exception as e:
    print(f"Solver error: {e}")
    status = "error"

# Write solution
os.makedirs("/app/submissions", exist_ok=True)
rows = []
if model.getNSols() > 0:
    for m in M:
        for p in PL:
            for prod in P:
                if (m, p, prod) in prod_reg:
                    v = model.getVal(prod_reg[(m, p, prod)])
                    if v > 1e-6:
                        rows.append(["regular_production", m, prod, p, "", "", f"{v:.8f}"])
                    v2 = model.getVal(prod_ot[(m, p, prod)])
                    if v2 > 1e-6:
                        rows.append(["overtime_production", m, prod, p, "", "", f"{v2:.8f}"])
                    sv = model.getVal(setup[(m, p, prod)])
                    if sv > 0.5:
                        rows.append(["product_setup", m, prod, p, "", "", "1"])
        for (p, dc), info in pdc_routes.items():
            for prod in P:
                if (m, p, dc, prod) in ship_pdc:
                    v = model.getVal(ship_pdc[(m, p, dc, prod)])
                    if v > 1e-6:
                        mode = lane_modes.get(("plant_dc", p, dc), ["RAIL"])[0]
                        rows.append(["ship_plant_dc", m, prod, p, dc, mode, f"{v:.8f}"])
        for (dc, c), info in dcr_routes.items():
            for prod in P:
                if (m, dc, c, prod) in ship_dcr:
                    v = model.getVal(ship_dcr[(m, dc, c, prod)])
                    if v > 1e-6:
                        mode = lane_modes.get(("dc_customer", dc, c), ["TRUCK"])[0]
                        rows.append(["ship_dc_customer", m, prod, dc, c, mode, f"{v:.8f}"])
        for dc in DC:
            for prod in P:
                if (m, dc, prod) in inv:
                    v = model.getVal(inv[(m, dc, prod)])
                    if v > 1e-6:
                        rows.append(["inventory", m, prod, dc, "", "", f"{v:.8f}"])
        for c in C:
            for prod in P:
                if (m, c, prod) in short:
                    v = model.getVal(short[(m, c, prod)])
                    if v > 1e-6:
                        rows.append(["shortage", m, prod, c, "", "", f"{v:.8f}"])

with open(OUT, "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["variable", "month", "item", "from", "to", "mode_id", "quantity_tons"])
    w.writerows(rows)

print(f"Wrote {len(rows)} rows to {OUT}")
model.free()
